<script>
(() => {
    const input = document.getElementById('quantity');
    const minus = document.querySelector('[data-quantity-minus]');
    const plus = document.querySelector('[data-quantity-plus]');
    if (!input || !minus || !plus) return;
    minus.hidden = false; plus.hidden = false;
    minus.addEventListener('click', () => { if (!input.value || !input.checkValidity()) input.value = input.min; else input.stepDown(); input.dispatchEvent(new Event('change', { bubbles: true })); });
    plus.addEventListener('click', () => { if (!input.value || !input.checkValidity()) input.value = input.min; else input.stepUp(); input.dispatchEvent(new Event('change', { bubbles: true })); });
})();
</script>
@endsection
